                          edge_n_used: np.ndarray) -> np.ndarray:
    n = len(local_opt_tour)
    new_dist = edge_distance.copy()

    # Collect tour edges as frozensets for fast lookup
    tour_edges = set()
    for i in range(n):
        a = local_opt_tour[i]
        b = local_opt_tour[(i + 1) % n]
        if a < b:
            tour_edges.add((a, b))
        else:
            tour_edges.add((b, a))

    # Determine small reward based on smallest positive distance
    positive = edge_distance[edge_distance > 0]
    min_dist = np.min(positive) if positive.size > 0 else 1.0
    penalty = 1.0
    reward = 0.1 * min_dist

    for i in range(n):
        for j in range(i + 1, n):
            if (i, j) in tour_edges:
                new_dist[i, j] += penalty * (1 + edge_n_used[i, j])
            else:
                if edge_n_used[i, j] == 0:
                    new_dist[i, j] = max(0.0, new_dist[i, j] - reward)
            new_dist[j, i] = new_dist[i, j]

    return new_dist

