def update_edge_distance(edge_distance: np.ndarray, local_opt_tour: np.ndarray,
                          edge_n_used: np.ndarray) -> np.ndarray:
    n = edge_distance.shape[0]
    # Build set of undirected edges in the current local optimum tour (including closing edge)
    tour_edges = set()
    for i in range(n):
        u = local_opt_tour[i]
        v = local_opt_tour[(i+1) % n]
        if u < v:
            tour_edges.add((u, v))
        else:
            tour_edges.add((v, u))

    c_tour = 0.5      # additive penalty multiplier for tour edges
    c_other = 0.1     # additive penalty multiplier for non-tour edges

    penalty = np.zeros_like(edge_distance)
    for i in range(n):
        for j in range(i+1, n):
            used = edge_n_used[i, j]
            if (i, j) in tour_edges:
                penalty[i, j] = c_tour * (1 + used)
            else:
                penalty[i, j] = c_other * used
            penalty[j, i] = penalty[i, j]

    return edge_distance + penalty

import numpy as np

def update_edge_distance(edge_distance: np.ndarray, local_opt_tour: np.ndarray,
                          edge_n_used: np.ndarray) -> np.ndarray:
    n = edge_distance.shape[0]
    # Build set of undirected edges in the current local optimum tour (including closing edge)
    tour_edges = set()
    for i in range(n):
        u = local_opt_tour[i]
        v = local_opt_tour[(i+1) % n]
        if u < v:
            tour_edges.add((u, v))
        else:
            tour_edges.add((v, u))

    lam = 0.2  # scaling factor for exponential
    new_dist = edge_distance.copy()
    for i in range(n):
        for j in range(i+1, n):
            usage = edge_n_used[i, j]
            if (i, j) in tour_edges:
                factor = np.exp(lam * usage)
            else:
                factor = np.exp(-lam * usage)
            new_dist[i, j] = edge_distance[i, j] * factor
            new_dist[j, i] = new_dist[i, j]
    return new_dist

def update_edge_distance(edge_distance: np.ndarray, local_opt_tour: np.ndarray,
                          edge_n_used: np.ndarray) -> np.ndarray:
    n = edge_distance.shape[0]
    # Build set of undirected edges in the current local optimum tour (including closing edge)
    tour_edges = set()
    for i in range(n):
        u = local_opt_tour[i]
        v = local_opt_tour[(i+1) % n]
        if u < v:
            tour_edges.add((u, v))
        else:
            tour_edges.add((v, u))

    c_tour = 0.7      # extra multiplier for edges in the tour
    c_other = 0.15    # multiplier for edges not in the tour

    new_dist = edge_distance.copy()
    for i in range(n):
        for j in range(i+1, n):
            indicator = 1 if (i, j) in tour_edges else 0
            used = edge_n_used[i, j]
            if indicator:
                factor = 1 + c_tour * (1 + used ** 2)
            else:
                factor = 1 + c_other * (used ** 2)
            new_dist[i, j] = edge_distance[i, j] * factor
            new_dist[j, i] = new_dist[i, j]

    return new_dist
